public final class Config {
  private Config() {}
  private static class Holder { static final Config INSTANCE = new Config(); }
  public static Config getInstance() { return Holder.INSTANCE; }
}

public class Pizza {
  private final int size; private final boolean cheese;
  private Pizza(Builder b) { size = b.size; cheese = b.cheese; }
  public static class Builder {
    private final int size; private boolean cheese;
    public Builder(int size) { this.size = size; }
    public Builder cheese(boolean c) { cheese = c; return this; }
    public Pizza build() { return new Pizza(this); }
  }
}

