def log_calls(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        print(f"calling {fn.__name__}")
        return fn(*args, **kwargs)
    return wrapper

class Subject {
  private final List<Consumer<String>> subs = new CopyOnWriteArrayList<>();
  void subscribe(Consumer<String> c) { subs.add(c); }
  void publish(String msg) { subs.forEach(c -> c.accept(msg)); }
}
